-- SRV-01: Postgres 18 identity storage foundation only.
-- Enrollment, device certificate verification and user authorization are NOT implemented.
-- Each ID is generated by native PostgreSQL uuidv7(), never MAC/IP/hostname.
CREATE TABLE device_groups (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    name VARCHAR(120) NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE devices (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    group_id UUID NOT NULL REFERENCES device_groups (id),
    enrollment_state VARCHAR(32) NOT NULL
        CHECK (enrollment_state IN ('pending_certificate', 'active', 'revoked', 'retired')),
    hostname VARCHAR(255),
    device_label VARCHAR(255),
    asset_tag VARCHAR(128),
    replaces_device_id UUID REFERENCES devices (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    enrolled_at TIMESTAMPTZ,
    last_seen_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    CONSTRAINT devices_not_self_replacing CHECK (replaces_device_id IS DISTINCT FROM id)
);

CREATE INDEX devices_group_idx ON devices (group_id);

-- Pending public CSRs are reviewed by an authorized administrator offline.
-- CSR-supplied subject/SAN values are NOT authorization.
CREATE TABLE device_enrollment_csrs (
    device_id UUID PRIMARY KEY REFERENCES devices (id),
    csr_pem_public TEXT NOT NULL,
    csr_sha256_digest CHAR(64) NOT NULL,
    csr_spki_digest CHAR(64) NOT NULL,
    requested_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    pending_expires_at TIMESTAMPTZ NOT NULL,
    reviewed_by UUID,
    reviewed_at TIMESTAMPTZ
);

CREATE TABLE device_credentials (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    device_id UUID NOT NULL REFERENCES devices (id),
    client_cert_sha256_fingerprint CHAR(64) NOT NULL UNIQUE,
    issuer_id VARCHAR(255) NOT NULL,
    serial_number VARCHAR(128) NOT NULL,
    csr_spki_digest CHAR(64) NOT NULL,
    status VARCHAR(16) NOT NULL
        CHECK (status IN ('pending', 'active', 'revoked')),
    issued_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    CONSTRAINT device_credential_validity CHECK (expires_at > issued_at),
    CONSTRAINT device_cert_issuer_serial_unique UNIQUE (issuer_id, serial_number),
    CONSTRAINT device_cert_fingerprint_hex CHECK (client_cert_sha256_fingerprint ~ '^[0-9a-f]{64}$')
);

CREATE INDEX device_credentials_by_device ON device_credentials (device_id);

-- Random single-use high-entropy pairing tokens; only a verifier is stored.
CREATE TABLE enrollment_tokens (
    id UUID PRIMARY KEY DEFAULT uuidv7(),
    token_sha256 BYTEA NOT NULL UNIQUE CHECK (octet_length(token_sha256) = 32),
    group_id UUID NOT NULL REFERENCES device_groups (id),
    policy_notice_version BIGINT NOT NULL CHECK (policy_notice_version > 0),
    expires_at TIMESTAMPTZ NOT NULL,
    consumed_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
